// src/pages/services/web-design-development.tsx
import * as React from "react";
import type { HeadFC, PageProps } from "gatsby";
import { graphql } from "gatsby";
import { useTranslation } from "gatsby-plugin-react-i18next";
import Link from "../../components/AppLink";
import Layout from "../layout";
import data from "../../data/data.json";
import type { Company } from "../../interfaces";
import { useEffect } from "react";
import images from "../../images";
import SEO from "../../components/seo";

const info: Company = data[0];

type Chip = { chip: string };
type Outcome = { title: string; text: string };
type ListItem = { item: string };
type Step = { title: string; text: string };
type Faq = { q: string; a: string };

const WebDesignDevelopmentPage: React.FC<PageProps> = () => {
  const { t, i18n } = useTranslation();
  const language = i18n.language;

  useEffect(() => {
    document.body.style.backgroundImage = `url(${images.bg.src})`;
    document.body.style.backgroundSize = "cover";
    document.body.style.backgroundPosition = "center";
    document.body.style.backgroundRepeat = "no-repeat";

    return () => {
      document.body.style.backgroundImage = "";
      document.body.style.backgroundSize = "";
      document.body.style.backgroundPosition = "";
      document.body.style.backgroundRepeat = "";
    };
  }, []);

  // Hero chips
  const heroChips = t("services.webDesignDevelopment.hero.chips", {
    returnObjects: true,
  }) as Chip[];

  // Sections data
  const outcomes = t("services.webDesignDevelopment.sections.outcomes.items", {
    returnObjects: true,
  }) as Outcome[];

  const idealFor = t("services.webDesignDevelopment.sections.idealFor.items", {
    returnObjects: true,
  }) as ListItem[];

  const deliverables = t(
    "services.webDesignDevelopment.sections.deliverables.items",
    { returnObjects: true }
  ) as ListItem[];

  const steps = t("services.webDesignDevelopment.sections.process.steps", {
    returnObjects: true,
  }) as Step[];

  const tech = t("services.webDesignDevelopment.sections.tech.items", {
    returnObjects: true,
  }) as ListItem[];

  const monthlyBullets = t(
    "services.webDesignDevelopment.sections.monthlyUpdates.bullets",
    { returnObjects: true }
  ) as ListItem[];

  const faq = t("services.webDesignDevelopment.sections.faq.items", {
    returnObjects: true,
  }) as Faq[];

  const mailSubject = encodeURIComponent(
    t("services.webDesignDevelopment.hero.secondaryCta") ||
      "Website Audit Request"
  );
  const mailtoAudit = `mailto:${info.email}?subject=${mailSubject}`;

  return (
    <Layout data={info}>
      <SEO
        data={info}
        titleKey="services.webDesignDevelopment.metaTitle"
        descriptionKey="services.webDesignDevelopment.metaDescription"
        pathname="/services/web-design-development/"
        schemaType="ProfessionalService"
      />
      {/* HERO */}
      <section className={"pt-10 pb-6 sm:pt-14 sm:pb-10"}>
        <div className={styles.container}>
          <div className="text-center">
            <h1 className="text-3xl sm:text-5xl poppins-bold text-light mx-auto max-w-4xl">
              {t("services.webDesignDevelopment.hero.title")}
            </h1>

            <p className="mt-4 text-lg sm:text-2xl poppins-regular text-light/90 mx-auto max-w-4xl">
              {t("services.webDesignDevelopment.hero.subtitle")}
            </p>

            {/* CTAs */}
            <div className="mx-auto mt-8 flex flex-col sm:flex-row items-center justify-center gap-3">
              <Link
                to="/contact/"
                className="rounded-full bg-secondary px-5 py-2.5 text-light text-center"
              >
                {t("services.webDesignDevelopment.hero.primaryCta")}
              </Link>

              <a
                href={mailtoAudit}
                className="rounded-full bg-purplesemilight px-5 py-2.5 text-light text-center"
              >
                {t("services.webDesignDevelopment.hero.secondaryCta")}
              </a>
            </div>

            {/* Proof chips */}
            {Array.isArray(heroChips) && heroChips.length > 0 ? (
              <div className="mx-auto mt-6 flex flex-wrap items-center justify-center gap-2 max-w-4xl">
                {heroChips.map((c, idx) => (
                  <span
                    key={`${c.chip}-${idx}`}
                    className="inline-flex items-center rounded-full border border-white/20 bg-white/10 px-3 py-1 text-sm text-light/90"
                  >
                    {c.chip}
                  </span>
                ))}
              </div>
            ) : null}

            {/* Optional micro-proof line */}
            <p className="mx-auto mt-6 text-sm text-light/70 max-w-3xl">
              {language === "en"
                ? "Best for businesses that launch campaigns, update offers, and evolve monthly."
                : language === "fr"
                ? "Idéal pour les entreprises qui lancent des campagnes, mettent à jour leurs offres et évoluent chaque mois."
                : "Ideal para negocios que lanzan campañas, actualizan ofertas y evolucionan mes a mes."}
            </p>
          </div>
        </div>
      </section>

      {/* OUTCOMES */}
      <section className="py-10 sm:py-14">
        <div className={styles.container}>
          <h2 className="text-2xl sm:text-4xl text-center poppins-regular text-verde">
            {t("services.webDesignDevelopment.sections.outcomes.title")}
          </h2>

          <div className="mt-8 grid grid-cols-1 md:grid-cols-2 gap-4">
            {Array.isArray(outcomes)
              ? outcomes.map((o, idx) => (
                  <div key={`${o.title}-${idx}`} className={styles.card}>
                    <h3 className={styles.cardTitle}>{o.title}</h3>
                    <p className="mt-2 text-sm sm:text-base text-light/70 leading-relaxed">
                      {o.text}
                    </p>
                  </div>
                ))
              : null}
          </div>
        </div>
      </section>

      {/* IDEAL FOR */}
      <section className="py-10 sm:py-14">
        <div className={styles.container}>
          <h2 className="text-2xl sm:text-4xl text-center poppins-regular text-verde">
            {t("services.webDesignDevelopment.sections.idealFor.title")}
          </h2>

          <div className="mt-8 mx-auto max-w-4xl">
            <ul className="grid grid-cols-1 sm:grid-cols-2 gap-3">
              {Array.isArray(idealFor)
                ? idealFor.map((x, idx) => (
                    <li key={`${x.item}-${idx}`} className={styles.card}>
                      <p className="text-sm sm:text-base text-light/80">
                        {x.item}
                      </p>
                    </li>
                  ))
                : null}
            </ul>
          </div>
        </div>
      </section>

      {/* DELIVERABLES */}
      <section className="py-10 sm:py-14">
        <div className={styles.container}>
          <h2 className="text-2xl sm:text-4xl text-center poppins-regular text-verde">
            {t("services.webDesignDevelopment.sections.deliverables.title")}
          </h2>

          <div className="mt-8 mx-auto max-w-4xl">
            <div className={styles.card}>
              <ul className="list-disc pl-5 space-y-2 text-sm sm:text-base text-light/80">
                {Array.isArray(deliverables)
                  ? deliverables.map((d, idx) => (
                      <li key={`${d.item}-${idx}`}>{d.item}</li>
                    ))
                  : null}
              </ul>
            </div>
          </div>
        </div>
      </section>

      {/* PROCESS */}
      <section className="py-10 sm:py-14">
        <div className={styles.container}>
          <h2 className="text-2xl sm:text-4xl text-center poppins-regular text-verde">
            {t("services.webDesignDevelopment.sections.process.title")}
          </h2>

          <div className="mt-8 grid grid-cols-1 md:grid-cols-2 gap-4">
            {Array.isArray(steps)
              ? steps.map((s, idx) => (
                  <div key={`${s.title}-${idx}`} className={styles.card}>
                    <div className="flex items-center gap-3">
                      <span className="inline-flex h-7 w-7 items-center justify-center rounded-full border border-black/10 bg-white text-sm font-semibold text-dark/70">
                        {idx + 1}
                      </span>
                      <h3 className={styles.cardTitle}>{s.title}</h3>
                    </div>
                    <p className={styles.cardText}>{s.text}</p>
                  </div>
                ))
              : null}
          </div>
        </div>
      </section>

      {/* TECH */}
      <section className="py-10 sm:py-14">
        <div className={styles.container}>
          <h2 className="text-2xl sm:text-4xl text-center poppins-regular text-verde">
            {t("services.webDesignDevelopment.sections.tech.title")}
          </h2>

          <div className="mt-8 mx-auto max-w-4xl">
            <div className={styles.card}>
              <ul className="list-disc pl-5 space-y-2 text-sm sm:text-base text-light/80">
                {Array.isArray(tech)
                  ? tech.map((x, idx) => (
                      <li key={`${x.item}-${idx}`}>{x.item}</li>
                    ))
                  : null}
              </ul>
            </div>
          </div>
        </div>
      </section>

      {/* MONTHLY UPDATES */}
      <section className="py-10 sm:py-14">
        <div className={styles.container}>
          <div className="mx-auto max-w-4xl">
            <h2 className="text-2xl sm:text-4xl text-center poppins-regular text-verde">
              {t("services.webDesignDevelopment.sections.monthlyUpdates.title")}
            </h2>

            <p className="mt-6 text-sm sm:text-base text-center text-light/70 leading-relaxed">
              {t("services.webDesignDevelopment.sections.monthlyUpdates.text")}
            </p>

            <div className="mt-8">
              <div className={styles.card}>
                <ul className="list-disc pl-5 space-y-2 text-sm sm:text-base text-light/80">
                  {Array.isArray(monthlyBullets)
                    ? monthlyBullets.map((x, idx) => (
                        <li key={`${x.item}-${idx}`}>{x.item}</li>
                      ))
                    : null}
                </ul>
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* FAQ */}
      <section className="py-10 sm:py-14">
        <div className={styles.container}>
          <h2 className="text-2xl sm:text-4xl text-center poppins-regular text-verde">
            {t("services.webDesignDevelopment.sections.faq.title")}
          </h2>

          <div className="mt-8 mx-auto max-w-4xl space-y-3">
            {Array.isArray(faq)
              ? faq.map((x, idx) => (
                  <details key={`${x.q}-${idx}`} className={styles.card}>
                    <summary className="cursor-pointer text-sm sm:text-base font-semibold text-light/90">
                      {x.q}
                    </summary>
                    <p className={styles.cardText}>{x.a}</p>
                  </details>
                ))
              : null}
          </div>
        </div>
      </section>

      {/* FINAL CTA */}
      <section className="py-12 sm:py-16">
        <div className={styles.container}>
          <div className="mx-auto max-w-4xl text-center">
            <h2 className="text-2xl sm:text-4xl poppins-regular text-verde">
              {t("services.webDesignDevelopment.sections.finalCta.title")}
            </h2>
            <p className="mt-4 text-sm sm:text-base text-light/70">
              {t("services.webDesignDevelopment.sections.finalCta.subtitle")}
            </p>

            <div className="mt-8 flex flex-col sm:flex-row items-center justify-center gap-3">
              <Link
                to="/contact/"
                className="rounded-full bg-secondary px-5 py-2.5 text-light text-center"
              >
                {t(
                  "services.webDesignDevelopment.sections.finalCta.primaryCta"
                )}
              </Link>

              <a
                href={mailtoAudit}
                className="rounded-full bg-purplesemilight px-5 py-2.5 text-light text-center"
              >
                {t(
                  "services.webDesignDevelopment.sections.finalCta.secondaryCta"
                )}
              </a>
            </div>
          </div>
        </div>
      </section>
    </Layout>
  );
};

export default WebDesignDevelopmentPage;

export const Head: HeadFC = () => {
  // Note: If your build complains about hooks in Head, move this into a reusable SEO component.
  const { t } = useTranslation();

  return (
    <>
      <title>{t("services.webDesignDevelopment.metaTitle")}</title>
      <meta
        name="description"
        content={t("services.webDesignDevelopment.metaDescription") || ""}
      />
    </>
  );
};

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

const styles = {
  sectionWrapper:
    "border-2 w-full sm:w-[1024px] mx-auto rounded-xl p-2 sm:p-8 mt-8 bg-darkBg/50",
  labelTitle: "text-2xl sm:text-4xl text-center poppins-regular text-verde",
  container: "mx-auto w-full max-w-6xl px-4 sm:px-6",
  card: "rounded-2xl border border-black/10 bg-primary/70 p-5 shadow-sm supports-[backdrop-filter]:bg-purplesemilight/40 supports-[backdrop-filter]:backdrop-blur text-light",
  cardTitle: "text-base sm:text-lg font-semibold text-light/90",
  cardText: "mt-3 text-sm sm:text-base text-light/70 leading-relaxed",
};
